   607	    """In-memory deterministic model stepped at a fixed two-second interval."""
   608	
   609	    def __init__(self, seed: int = 42):
   610	        self.seed = seed
   611	        self.tick = 0
   612	        self.active_scenario = "none"
   613	        self.scenario_zone: str | None = None
   614	
   615	    def start_scenario(self, scenario: str, zone: str | None = None) -> None:
   616	        if scenario not in VALID_SCENARIOS:
   617	            raise ValueError(f"unknown scenario: {scenario}")
   618	        if scenario in {"methane_release", "blocked_working"} and zone not in MINING_SECTIONS:
   619	            raise ValueError(f"{scenario} requires zone section_a or section_b")
   620	        if scenario == "fire":
   621	            zone = zone or "main_drift"
   622	            if zone not in FIRE_ZONES:
   623	                raise ValueError("fire requires zone main_drift, section_a or section_b")
   624	        if scenario == "main_fan_failure":
   625	            zone = "shaft"
   626	        self.active_scenario = scenario
   627	        self.scenario_zone = zone
   628	
   629	    def reset(self) -> None:
   630	        self.tick = 0
   631	        self.active_scenario = "none"
   632	        self.scenario_zone = None
   633	
   634	    def step(self) -> dict[str, Any]:
   635	        self.tick += 1
   636	        return self.snapshot()
   637	
   638	    def _normal_sensors(self) -> dict[str, dict[str, float]]:
   639	        sensors: dict[str, dict[str, float]] = {}
   640	        for zone in ZONE_ORDER:
   641	            rng = random.Random(f"{self.seed}:{self.tick}:{zone}")
   642	            base = BASE_SENSORS[zone]
   643	            sensors[zone] = {
   644	                "methane_pct": round(base["methane_pct"] + rng.uniform(-0.025, 0.025), 3),
   645	                "co_ppm": round(base["co_ppm"] + rng.uniform(-0.7, 0.7), 1),
   646	                "smoke_index": round(max(0.0, base["smoke_index"] + rng.uniform(-0.006, 0.006)), 3),
   647	                "temperature_c": round(base["temperature_c"] + rng.uniform(-0.4, 0.4), 1),
   648	                "airflow_mps": round(BASE_AIRFLOW_MPS[zone] + rng.uniform(-0.08, 0.08), 2),
   649	            }
   650	        return sensors
   651	
   652	    def _active_edges(self) -> tuple[tuple[str, str], ...]:
   653	        if self.active_scenario == "blocked_working" and self.scenario_zone:
   654	            blocked = ("main_drift", self.scenario_zone)
   655	            return tuple(edge for edge in AIRFLOW_EDGES if edge != blocked)
   656	        return AIRFLOW_EDGES
   657	
   658	    def _apply_scenario(self, sensors: dict[str, dict[str, float]]) -> None:
   659	        scenario = self.active_scenario
   660	        source = self.scenario_zone
   661	        if scenario == "none":
   662	            return
   663	        if scenario == "main_fan_failure":
   664	            failed_flow = {
   665	                "shaft": 0.20,
   666	                "main_drift": 0.22,
   667	                "section_a": 0.12,
   668	                "section_b": 0.12,
   669	                "refuge_chamber": 0.65,
   670	            }
   671	            for zone, value in failed_flow.items():
   672	                sensors[zone]["airflow_mps"] = value
   673	            return
   674	        if scenario == "blocked_working" and source:
   675	            sensors[source]["airflow_mps"] = 0.10
   676	            sensors[source]["methane_pct"] = 1.25
   677	            return
   678	        if scenario == "methane_release" and source:
   679	            sensors[source]["methane_pct"] = 2.80
   680	            return
   681	        if scenario == "fire" and source:
   682	            distances = downstream_zones(source, self._active_edges())
   683	            for zone, distance in distances.items():
   684	                factor = 0.55 ** distance
   685	                sensors[zone]["co_ppm"] = round(max(sensors[zone]["co_ppm"], 75.0 * factor), 1)
   686	                sensors[zone]["smoke_index"] = round(max(sensors[zone]["smoke_index"], 0.8 * factor), 3)
   687	                sensors[zone]["temperature_c"] = round(max(sensors[zone]["temperature_c"], 58.0 * factor), 1)
   688	
   689	    def snapshot(self) -> dict[str, Any]:
   690	        sensors = self._normal_sensors()
