   695	            {
   696	                "from": start,
   697	                "to": end,
   698	                "active": (start, end) in active_edges,
   699	                "direction": "supply",
   700	            }
   701	            for start, end in AIRFLOW_EDGES
   702	        ]
   703	        fans = {
