   707	                "speed_percent": 0 if self.active_scenario == "main_fan_failure" else 100,
   708	            },
   709	            "fan-aux-a": {"zone": "section_a", "state": "running", "speed_percent": 75},
   710	            "fan-aux-b": {"zone": "section_b", "state": "running", "speed_percent": 75},
   711	        }
   712	        workers = {
